shellCommands.command:
cd /workspace && cat > next.config.ts <<'EOF'
import type { NextConfig } from 'next'

const nextConfig: NextConfig = {
  experimental: {
    // Enables forbidden() / unauthorized() from next/navigation
    authInterrupts: true,
  },
}

export default nextConfig
EOF
mkdir -p app/admin
cat > app/admin/page.tsx <<'EOF'
import { forbidden, unauthorized } from 'next/navigation'
import { verifyAdmin } from '@/app/lib/auth'

export default async function AdminPage() {
  const { isAdmin, session } = await verifyAdmin()

  // Not signed in -> 401, renders app/admin/unauthorized.tsx
  if (!session) {
    unauthorized()
  }

  // Signed in but lacking the admin role -> 403, renders app/admin/forbidden.tsx
  if (!isAdmin) {
    forbidden()
  }

  return (
    <main>
      <h1>Admin Dashboard</h1>
      <p>Welcome, {session.name}!</p>
    </main>
  )
}
EOF
